mapper.select:
SELECT t.target_type AS "targetType",t.target_id AS "targetId",t.target_name AS "targetName", t.start_month AS "startMonth",t.end_month AS "endMonth" FROM ( SELECT 'project' AS target_type,p.PROJ_ID AS target_id,p.PROJ_NM AS target_name, to_char(p.CTRT_BGN_DT,'YYYYMM') AS start_month,to_char(p.CTRT_END_DT,'YYYYMM') AS end_month FROM TB_PJ_PROJ p WHERE p.PROJ_STAT_CD='ING' AND p.CTRT_TYPE_CD!='IN' UNION ALL SELECT 'opportunity' AS target_type,o.OPP_ID AS target_id,o.OPP_NM AS target_name, o.BGN_PLAN_YM AS start_month,NULL::text AS end_month FROM TB_SL_OPP o WHERE o.OPP_STAT_CD='ING' AND (o.CTRT_TYPE_CD IS NULL OR o.CTRT_TYPE_CD!='IN') ) t
AND t.target_type=#{targetType} AND t.target_id=#{targetId}
ORDER BY t.target_name,t.target_id,t.target_type
